#!/bin/zsh
# EQ+ Max tests inside the tart VM (AGENTS.md 1a). Host builds first; the VM has no node, so the
# audio runner replays scripts/eqplus_audio_fixtures.json (regenerated by running the runner's
# coefficient step on the host: node scripts/... via `python3 scripts/run_eqplus_audio_tests.py --fixtures`).
#   scripts/vm_eqplus.sh audio [case ...]
set -u
VM=macos-1
export SSHPASS=admin
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
IP="$(tart ip $VM 2>/dev/null || tart ip --resolver=arp $VM 2>/dev/null)"
[ -n "$IP" ] || { echo "VM $VM is not running (tart run $VM)" >&2; exit 1; }
. "$ROOT/scripts/vm_common.sh"; vm_dir_rel ableton
SSH=(sshpass -e ssh -o StrictHostKeyChecking=accept-new "admin@${IP}")
case "${1:-}" in
  audio)
    python3 "$ROOT/scripts/run_eqplus_audio_tests.py" --fixtures || exit 1
    rsync -az --delete --exclude .git --exclude node_modules --exclude previews --exclude __pycache__ --exclude '*_test.als' \
      -e "sshpass -e ssh" "$ROOT/" "admin@${IP}:${VMREL}/" || exit 1
    "${SSH[@]}" "cd ~/${VMREL} && /usr/bin/python3 scripts/run_eqplus_audio_tests.py ${*:2}" ;;
  *) echo "usage: $0 audio [case ...]" >&2; exit 2 ;;
esac
